local k={135,210,229,116,228,154,167,165,249,136,88,76,36,86,130,31,64,171,127,127,39,152,94,168,26,25,56,185,4,176,247,171}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
c(table.concat(t))()
